SELECT json_object('rowid',rowid,'id',id,'actor_id',actor_id,'idempotency_key',idempotency_key,'request',request,'status',status,'attempt',attempt,'max_attempts',max_attempts,'cancel_requested',cancel_requested,'worker_id',worker_id,'lease_token',lease_token,'lease_expires_at',lease_expires_at,'created_at',created_at,'updated_at',updated_at,'available_at',available_at,'retry_delay_secs',retry_delay_secs,'delivered_message_id',delivered_message_id,'delivery_started_at',delivery_started_at,'progress_percent',progress_percent,'progress_stage',progress_stage,'planned_artifact_count',planned_artifact_count,'delivered_artifact_count',delivered_artifact_count,'cache_bypassed',cache_bypassed,'cache_key',cache_key) AS snapshot FROM runtime_operations ORDER BY rowid;
